selector_to_html = {"a[href=\"#glibc-glibcxx\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u95ee\uff1a\u8fd0\u884c\u65f6\u62a5\u544a\u627e\u4e0d\u5230 GLIBC / GLIBCXX \u7248\u672c\uff1f<a class=\"headerlink\" href=\"#glibc-glibcxx\" title=\"Link to this heading\">#</a></h3><p>\u7b54\uff1a\u68c0\u67e5\u60a8\u73af\u5883\u652f\u6301\u7684\u7248\u672c\uff0c\u5e76\u5728\u9700\u8981\u65f6\u4f7f\u7528 LD_PRELOAD\uff08aarch64 \u8def\u5f84\uff09\uff1a</p>", "a[href=\"#arm64-cpu\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5728 Arm64 CPU \u4e0a\u5b89\u88c5<a class=\"headerlink\" href=\"#arm64-cpu\" title=\"Link to this heading\">#</a></h1><p>\u5728 Arm64 CPU \u4e0a\u5b89\u88c5 FlagTree \u4e4b\u524d\uff0c\u8bf7\u9605\u8bfb\u4ee5\u4e0b\u6ce8\u610f\u4e8b\u9879\uff1a</p>", "a[href=\"../user_guide/use-tle-cpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u4f7f\u7528 TLE-CPU<a class=\"headerlink\" href=\"#tle-cpu\" title=\"Link to this heading\">#</a></h1><p>\u672c\u8282\u4ecb\u7ecd\u5982\u4f55\u4f7f\u7528 TLE-CPU\u3002TLE-CPU \u5728 trition_3.3.x \u5206\u652f\u4e0a\u53ef\u7528\u3002</p><p>TLE-CPU \u63d0\u4f9b\u7edf\u4e00\u7684\u7f16\u7a0b\u8303\u5f0f\uff0c\u8986\u76d6\u591a\u6837\u5316\u7684\u8fb9\u7f18\u7aef CPU \u7b97\u529b\u3002\u5c06 TLE \u201c\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">@triton.jit</span></code> \u4e4b\u4e0a\u5206\u5c42\u786c\u4ef6\u6df1\u5ea6\u4f18\u5316\u201d\u7684\u7406\u5ff5\u6269\u5c55\u5230 CPU\u3002\u9488\u5bf9\u8fb9\u7f18 AI \u788e\u7247\u5316\u7684 CPU \u751f\u6001\uff08Arm64 / RISC-V / x86\uff0c\u591a\u79cd ISA \u5e76\u5b58\uff09\uff0c\u4f7f\u7528\u76f8\u540c\u7684 Triton \u7f16\u7a0b\u6a21\u578b\u548c\u96c6\u6210\u6846\u67b6\u6765\u652f\u6301\u4e0d\u540c\u7684 ISA\uff1a\u7f16\u7a0b\u6a21\u578b\u548c\u6b63\u786e\u6027\u8de8 ISA \u5171\u4eab\uff08\u666e\u901a Triton \u901a\u8fc7 LLVM \u843d\u5230\u4efb\u610f ISA\uff09\uff0c\u800c\u6bcf\u4e2a ISA \u7684\u9ad8\u6027\u80fd\u5b9e\u73b0\uff08intrinsic / C \u8fd0\u884c\u65f6\uff09\u5219\u5206\u522b\u8d21\u732e\u3002\u6a21\u578b\u4ee3\u7801\u901a\u8fc7\u7b97\u5b50\u5e93\uff08FlagGems\uff09\u7684 vendor \u5206\u53d1\u8def\u7531\u5230\u5bf9\u5e94\u7684 ISA \u5b9e\u73b0\uff0c\u65e0\u9700\u611f\u77e5\u5177\u4f53 ISA\u3002CPU \u4e0e GPU \u7684\u5dee\u5f02\u51b3\u5b9a\u4e86\u5b83\u9700\u8981\u4e00\u4e2a\u72ec\u7acb\u7684\u6269\u5c55\u9762\uff1a</p>", "a[href=\"#id7\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5e38\u89c1\u95ee\u9898<a class=\"headerlink\" href=\"#id7\" title=\"Link to this heading\">#</a></h2><h3>\u95ee\uff1a\u5728 big.LITTLE SoC \u4e0a\u6027\u80fd\u53ea\u6709\u4e00\u534a\uff1f<a class=\"headerlink\" href=\"#big-little-soc\" title=\"Link to this heading\">#</a></h3><p>\u7b54\uff1a\u5728\u5f02\u6784 SoC \u4e0a\uff08\u4f8b\u5982 Cortex-A720 \u5927\u6838 + A520 \u5c0f\u6838\uff09\uff0c\u59cb\u7ec8\u4f7f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">taskset</span></code> \u5c06\u8fdb\u7a0b\u7ed1\u5b9a\u5230<strong>\u4ec5\u5927\u6838</strong> \u2014 \u5c0f\u6838\u8fdb\u5165 OMP \u7ebf\u7a0b\u6c60\u4f1a\u5728\u5c4f\u969c\u5904\u505c\u6ede\uff0c\u5bfc\u81f4\u6574\u4f53\u6027\u80fd\u635f\u5931\u7ea6 2 \u500d\u3002\u540c\u65f6\u5c06\u8c03\u5ea6\u5668\u8bbe\u7f6e\u4e3a performance \u6a21\u5f0f\uff1a</p>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. \u6784\u5efa\u548c\u8fd0\u884c\u73af\u5883<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><h3>1.1 \u7cfb\u7edf\u4f9d\u8d56<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#id5\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.2 \u4ece\u6e90\u7801\u6784\u5efa<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h3><p>\u4e09\u4e2a\u6b65\u9aa4\uff1a<strong>\u514b\u9686 FlagTree \u2192 \u901a\u8fc7\u8f85\u52a9\u811a\u672c\u8fde\u63a5 flagtree-cpu \u2192 \u6784\u5efa FlagTree</strong>\u3002</p>", "a[href=\"#kernel-s-error-junk-at-end-of-line-first-unrecognized-character-is\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u95ee\uff1a\u5185\u6838\u7f16\u8bd1\u5931\u8d25\uff0c\u62a5\u9519 <code class=\"docutils literal notranslate\"><span class=\"pre\">kernel.s:</span> <span class=\"pre\">Error:</span> <span class=\"pre\">junk</span> <span class=\"pre\">at</span> <span class=\"pre\">end</span> <span class=\"pre\">of</span> <span class=\"pre\">line,</span> <span class=\"pre\">first</span> <span class=\"pre\">unrecognized</span> <span class=\"pre\">character</span> <span class=\"pre\">is</span> <span class=\"pre\">\\</span></code>\u201d``\uff1f<a class=\"headerlink\" href=\"#kernel-s-error-junk-at-end-of-line-first-unrecognized-character-is\" title=\"Link to this heading\">#</a></h3><p>\u7b54\uff1a\u5f53\u524d shell \u4e2d\u672a\u5bfc\u51fa <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGTREE_BACKEND=cpu</span></code>\u3002\u8fd9\u4e0d\u4ec5\u662f\u6784\u5efa\u65f6\u7684\u5f00\u5173 \u2014 <code class=\"docutils literal notranslate\"><span class=\"pre\">kernel.s</span></code> \u7684\u8fd0\u884c\u65f6 JIT \u7f16\u8bd1\u4e5f\u4f9d\u8d56\u5b83\uff08\u5b83\u542f\u7528\u4e86 GNU \u6c47\u7f16\u5668\u62d2\u7edd\u7684 LLVM <code class=\"docutils literal notranslate\"><span class=\"pre\">.file</span></code>/<code class=\"docutils literal notranslate\"><span class=\"pre\">.loc</span></code> \u8c03\u8bd5\u6307\u4ee4\u7684\u5265\u79bb\uff0c\u4ee5\u53ca ARM <code class=\"docutils literal notranslate\"><span class=\"pre\">-march</span></code> \u6807\u5fd7\uff09\u3002\u5bfc\u51fa\u540e\u91cd\u65b0\u8fd0\u884c\u3002</p>", "a[href=\"#id4\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.1 \u514d\u6e90\u7801\u5b89\u88c5<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h3><p>\u26a0\ufe0f ARM64 CPU \u540e\u7aef\u76ee\u524d\u5c1a\u65e0\u9884\u6784\u5efa\u7684 wheel\uff1b\u8bf7\u6309\u7167\u4e0b\u65b9 2.2 \u8282\u4ece\u6e90\u7801\u6784\u5efa\u3002</p>", "a[href=\"#import-triton-language-extra-cpu-tle-ops-no-module-named\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u95ee\uff1a<code class=\"docutils literal notranslate\"><span class=\"pre\">import</span> <span class=\"pre\">triton.language.extra.cpu.tle_ops</span></code> \u5931\u8d25\uff0c\u62a5\u9519 \u201cNo module named \u2026\u201d\uff1f<a class=\"headerlink\" href=\"#import-triton-language-extra-cpu-tle-ops-no-module-named\" title=\"Link to this heading\">#</a></h3><p>\u7b54\uff1a\u7b2c 2 \u6b65\u7684\u7b26\u53f7\u94fe\u63a5\u4e0d\u5b8c\u6574\u3002\u91cd\u65b0\u8fd0\u884c <code class=\"docutils literal notranslate\"><span class=\"pre\">bash</span> <span class=\"pre\">python/scripts/link_flagtree_cpu.sh</span></code> \u2014 \u5b83\u662f\u5e42\u7b49\u7684\uff0c\u5982\u679c\u4efb\u4f55\u9884\u671f\u7684\u7b26\u53f7\u94fe\u63a5\u65e0\u6cd5\u89e3\u6790\uff0c\u4f1a\u4ee5\u975e\u96f6\u9000\u51fa\u7801\u9000\u51fa\u3002</p>", "a[href=\"#id6\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. \u6d4b\u8bd5\u548c\u9a8c\u8bc1<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h2><p>\u26a0\ufe0f \u5728\u8fd0\u884c\u4efb\u4f55 JIT \u7f16\u8bd1\u5185\u6838\u7684\u64cd\u4f5c\u4e4b\u524d\uff08\u5305\u62ec\u4e0b\u9762\u7684\u9a8c\u8bc1\u811a\u672c\u4ee5\u53ca\u4e00\u822c\u7684\u6a21\u578b\u63a8\u7406\uff09\uff0c\u8bf7\u5bfc\u51fa <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGTREE_BACKEND=cpu</span></code> \u2014 \u5728\u8fd0\u884c\u65f6\uff0c\u5b83\u542f\u7528\u4e86 ARM <code class=\"docutils literal notranslate\"><span class=\"pre\">-march</span></code> \u6807\u5fd7\u3001OpenMP \u94fe\u63a5\u4ee5\u53ca\u9488\u5bf9\u751f\u6210 <code class=\"docutils literal notranslate\"><span class=\"pre\">kernel.s</span></code> \u7684 GCC \u6c47\u7f16\u5668\u517c\u5bb9\u6027\u5904\u7406\uff1a</p>", "a[href=\"#id2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.1 \u7cfb\u7edf\u4f9d\u8d56<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. \u5b89\u88c5\u547d\u4ee4<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><h3>2.1 \u514d\u6e90\u7801\u5b89\u88c5<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h3><p>\u26a0\ufe0f ARM64 CPU \u540e\u7aef\u76ee\u524d\u5c1a\u65e0\u9884\u6784\u5efa\u7684 wheel\uff1b\u8bf7\u6309\u7167\u4e0b\u65b9 2.2 \u8282\u4ece\u6e90\u7801\u6784\u5efa\u3002</p>", "a[href=\"#big-little-soc\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u95ee\uff1a\u5728 big.LITTLE SoC \u4e0a\u6027\u80fd\u53ea\u6709\u4e00\u534a\uff1f<a class=\"headerlink\" href=\"#big-little-soc\" title=\"Link to this heading\">#</a></h3><p>\u7b54\uff1a\u5728\u5f02\u6784 SoC \u4e0a\uff08\u4f8b\u5982 Cortex-A720 \u5927\u6838 + A520 \u5c0f\u6838\uff09\uff0c\u59cb\u7ec8\u4f7f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">taskset</span></code> \u5c06\u8fdb\u7a0b\u7ed1\u5b9a\u5230<strong>\u4ec5\u5927\u6838</strong> \u2014 \u5c0f\u6838\u8fdb\u5165 OMP \u7ebf\u7a0b\u6c60\u4f1a\u5728\u5c4f\u969c\u5904\u505c\u6ede\uff0c\u5bfc\u81f4\u6574\u4f53\u6027\u80fd\u635f\u5931\u7ea6 2 \u500d\u3002\u540c\u65f6\u5c06\u8c03\u5ea6\u5668\u8bbe\u7f6e\u4e3a performance \u6a21\u5f0f\uff1a</p>", "a[href=\"#pytorch\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.2 \u521b\u5efa\u865a\u62df\u73af\u5883\u5e76\u5b89\u88c5 PyTorch<a class=\"headerlink\" href=\"#pytorch\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#llvm\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.3 LLVM \u5de5\u5177\u94fe<a class=\"headerlink\" href=\"#llvm\" title=\"Link to this heading\">#</a></h3><p>\u5982\u679c <code class=\"docutils literal notranslate\"><span class=\"pre\">oaitriton.blob.core.windows.net</span></code> \u53ef\u8bbf\u95ee\uff0cLLVM \u5de5\u5177\u94fe\u4f1a\u5728\u9996\u6b21\u6784\u5efa\u65f6\uff08\u6b65\u9aa4 2.2 \u7b2c 3 \u6b65\uff09\u6839\u636e <code class=\"docutils literal notranslate\"><span class=\"pre\">cmake/llvm-hash.txt</span></code>\uff08a66376b0\uff09\u81ea\u52a8\u83b7\u53d6\u5e76\u7f13\u5b58\u5230 <code class=\"docutils literal notranslate\"><span class=\"pre\">~/.triton/llvm/</span></code> \u2014 <strong>\u65e0\u9700\u624b\u52a8\u64cd\u4f5c</strong>\u3002</p><p>\u5bf9\u4e8e\u53d7\u9650\u7f51\u7edc\u73af\u5883\uff0c\u8bf7\u624b\u52a8\u4e0b\u8f7d\uff08\u6ce8\u610f\u662f <strong>arm64</strong> \u5305\uff0c\u9002\u7528\u4e8e Triton 3.3\uff09\uff1a</p>"}
